function parseCatalog(text) {
  return text.trim().split('\n').filter(Boolean).map((line) => {
    const [name, category, caution] = line.split('|');
    return [name, category, caution];
  });
}
for (const [name, entries] of Object.entries(objectCatalog)) {
  add(`Biblioteca ampliada/Objetos/${name}`, table(['Objeto', 'Finalidade ou descrição', 'Contexto e cuidado'], parseCatalog(entries)));
}
const catalogObjects = Object.values(objectCatalog).flatMap(parseCatalog);
for (const [name, description, caution] of catalogObjects) {
  add(`Biblioteca ampliada/Objetos individuais/${name}`, `## Categoria\n${description}\n\n## Uso e contexto\n${caution}\n\n## Notas pessoais\nA preencher com observações próprias, modelo, tamanho, localização ou experiência.`);
}

