function addActionCatalog(name, text) {
  const rows = parseCatalog(text);
  add(`Biblioteca ampliada/Ações/${name}`, table(['Ação', 'O que envolve', 'Contexto e cuidado'], rows));
  for (const [action, description, caution] of rows) {
    add(`Biblioteca ampliada/Ações individuais/${action}`, `## O que é\n${description}\n\n## Como estruturar\n1. Defina o resultado esperado.\n2. Reúna o material ou contexto necessário.\n3. Faça uma etapa por vez.\n4. Confira o resultado.\n\n## Contexto e cuidado\n${caution}\n\n## Minhas notas\nA preencher com frequência, duração, preferências ou experiência própria.`);
  }
}
for (const [name, text] of Object.entries(actionCatalog)) addActionCatalog(name, text);

