for (const [name, text] of Object.entries(topicCatalog)) {
  const rows = parseCatalog(text);
  add(`Biblioteca ampliada/Referências/${name}`, table(['Tema', 'Descrição', 'Contexto e limite'], rows));
  for (const [term, description, caveat] of rows) {
    add(`Biblioteca ampliada/Referências individuais/${term}`, `## Descrição\n${description}\n\n## Contexto\n${caveat}\n\n## Fonte ou experiência\nRegistre origem, data e contexto caso acrescente uma afirmação específica.`);
  }
}

